DECLARE @TransIds_bettrans14 VARCHAR(MAX) = '114170546542,114170550987,114170585626,114170683396,114170695210,114170698064,114171202669,114171235759,114171238030,114171257701,114175906485,114175923062,114176110066,114176121303,114176734687,114177269743,114177275012,114177730246,114177748394,114178489246,114178563210,114178572179,114178771003,114178794014,114178916976,114178953886,114178974757,114179542624,114179596192,114179614005,114179663165,114184717443,114185028254,114185032922,114185034906,114185213672,114185224401,114185230271,114185435090,114185462197,114185479816,114185521013,114185794479,114185810768,114185877901,114185887928,114185947466,114186468170,114186640451,114186745385,114186780693,114187250815,114187251425,114187326335,114187330701,114187669561,114187716969,114187759456,114187806665,114187901473,114187912468,114188520502,114188767242,114189115519,114189223910,114189250178,114189298722,114189324078,114189324916,114189380092,114189380804'

CREATE TABLE #TransIds_bettrans14 (TransId BIGINT)
INSERT INTO #TransIds_bettrans14 (TransId)
SELECT	val AS TransId
FROM	dbo.f_SplitString(@TransIds_bettrans14, ',')
OPTION (maxrecursion 0)

--Insert into TicketVoiding_VoidedTransaction for bettrans14
DECLARE @ReasonId INT = 0 
INSERT INTO dbo.TicketVoiding_Reason (ReasonEnglish, ReasonChineseSimplified)
SELECT 'Abnormal bet',N'非正常投注'
	
SET @ReasonId = SCOPE_IDENTITY()

INSERT INTO dbo.TicketVoiding_VoidedTransaction (
	TransId
	,MessageId
	,ReasonId
	,MatchId
	,IssueTypeId
	,SubIssueTypeId
	,CustID
	)
SELECT t.TransId
	, 0 AS MessageId
	,@ReasonId
	,0
	,NULL
	,NULL
	,b.CustId
FROM #TransIds_bettrans14 t
	INNER JOIN bettrans14 b WITH (NOLOCK) ON b.transid = t.TransId
